one=np.ones_like(t)
def X(p):
    q,r,s,u=p
    return np.column_stack([one,t,t**2,A,A*t,A**q,A**r*t,A**s*e,e*A**u,e*one,e*A,A**2*t])
def res(p):
    M=X(p); c=np.linalg.lstsq(M,dA_dt,rcond=None)[0]
    return M@c-dA_dt
